#!/usr/bin/env python3
"""Assemble evidence report after final frozen-code checks, without acquisition."""
from pathlib import Path
import json,platform
import municipal_codes_cli as m
R=Path(__file__).resolve().parent
cities=m.read_json(R/'e2e-exports'/'results.json')
for c in cities:
 slug=c['slug'];c['standalone_browser']={'status':'blocked_http_403','failure_path':'standalone-final/'+slug+'/failure.json','reason':m.read_json(R/'standalone-final'/slug/'failure.json')['error']}
 p=R/'http-final'/slug/'receipt.json';c['direct_http']={'status':'blocked_http_403' if p.exists() and m.read_json(p)['http_status']==403 else 'see_retained_receipt','receipt_path':'http-final/'+slug+'/receipt.json'}
 c['cua_script']={'status':'bounded_acquisition_parse_export_pass','captures':[]}
 for p in sorted((R/'live-final'/slug).glob('*.receipt.json')):
  r=m.read_json(p);c['cua_script']['captures'].append(dict(path=str(p.relative_to(R)),accepted=r['accepted'],raw_sha256=r['sha256'],script_sha256=r['acquisition_script_sha256'],started_at=r['started_at'],finished_at=r['finished_at']))
 c['remaining_gates']=['Full inventory node classification, including substantive parent bodies, attachments, editorial/reference scope','Extra publication-family substantive collection and source/version closure','Full corpus acquisition, deduplication and disposition reconciliation; no full extraction performed','Official city route confirmation limitations remain as recorded in baseline report']
 if slug=='bellingham-wa':c['remaining_gates'].append('Charter Contents challenge retained; primary inventory postcheck recovered in distinct accepted attempt')
report=dict(schema_version=1,generated_at=m.now(),purpose='bounded current source acquisition and export validation; no production/import',whole_corpus_validated=False,environment=dict(python=platform.python_version(),platform=platform.platform(),node='v24.19.0',playwright='1.62.1',browser='isolated installed Google Chrome via Playwright; CUA Chrome extension browser 1',python_dependency_note='requests/beautifulsoup4 from existing review venv; LibreSSL warning retained, TLS validation enabled',node_dependency_note='Local host npm6 was incompatible with Node24; actual runtime used existing bundled Playwright1.62.1 via temporary local symlink. Clean machine: modern npm install package.json dependencies. No absolute workspace imports in delivered code.'),commands=dict(cua='README.md: supported CUA module example, e2e-plan.json jobs + five version-after jobs and distinct Bellingham postcheck',standalone='NODE_BINARY=node python run_standalone_validation.py standalone-final',http='python run_http_validation.py http-final',replay='python prepare_e2e.py --source live-final --out e2e-exports',regressions='python -m unittest -v test_municipal_codes validate_retained validate_live_snapshots test_e2e; node test_checksum.mjs'),code_freeze=m.read_json(R/'CODE-FREEZE.json'),tests_log='final-tests.log',cities=cities,limitations=['CUA module requires Codex documented cua API and current browser access; it is not a standalone Node transport','Standalone Playwright and direct HTTP tested separately; blocked responses do not qualify as legal acquisition','Retained capture v6 and final v7 differ only by immutable-receipt refusal guard; both source hashes retained. Earlier live-run is exploratory and excluded from E2E pass','Two batch calls timed out after completing some captures; completed immutable receipts retained and own tab resumed; final jobs executed in smaller batches','Body re-fetch and displayed currency equality bound the sampled chapter, not all legal nodes; primary inventory comparison is ordered node/parent/heading equality, not proof of all family scope'])
exclude={'E2E-VALIDATION.json','VALIDATION-REPORT.json','SHA256SUMS','CODE-FREEZE.json'}
report['artifact_hashes']={str(p.relative_to(R)):m.sha(p.read_bytes()) for p in sorted(R.rglob('*')) if p.is_file() and not any(part in ('node_modules','__pycache__') for part in p.relative_to(R).parts) and p.name not in exclude}
m.write_json(R/'E2E-VALIDATION.json',report)
# Existing verifier interface remains useful: bind current package without re-labeling baseline claims.
m.write_json(R/'VALIDATION-REPORT.json',dict(schema_version=2,report='E2E-VALIDATION.json',baseline_report='BASELINE-VALIDATION-REPORT.json',whole_corpus_validated=False,artifact_hashes=dict(report['artifact_hashes'],**{'E2E-VALIDATION.json':m.sha((R/'E2E-VALIDATION.json').read_bytes())})))
print('Report written for',len(cities),'cities;',len(report['artifact_hashes']),'hashed artifacts')
